static void create_ai_subpage(lv_obj_t *parent)
{
    lv_coord_t sw = lv_disp_get_hor_res(lv_disp_get_default());

    /* Column layout */
    lv_obj_set_flex_flow(parent, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(parent, CARD_GAP, 0);

    /* ── AI Hero card: ring + status ── */
    lv_obj_t *hero = lv_obj_create(parent);
    lv_obj_set_size(hero, lv_pct(100), DM(120));
    lv_obj_add_style(hero, &style_card, 0);
    lv_obj_set_style_pad_all(hero, 16, 0);
    lv_obj_set_scrollbar_mode(hero, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(hero, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_flex_flow(hero, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(hero, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(hero, 20, 0);

    /* AI ring */
    lv_obj_t *ring_cont = make_clean_cont(hero);
    lv_obj_set_size(ring_cont, DM(64), DM(64));

    lv_obj_t *ring = lv_arc_create(ring_cont);
    lv_obj_set_size(ring, DM(64), DM(64));
    lv_obj_center(ring);
    lv_arc_set_bg_angles(ring, 0, 360);
    lv_arc_set_angles(ring, 0, 300);
    lv_obj_set_style_arc_color(ring, lv_color_hex(COL_BLUE), 0);
    lv_obj_set_style_arc_opa(ring, LV_OPA_20, 0);
    lv_obj_set_style_arc_width(ring, 3, 0);
    lv_obj_remove_flag(ring, LV_OBJ_FLAG_CLICKABLE);

    lv_obj_t *ai_text = lv_label_create(ring_cont);
    lv_label_set_text(ai_text, "AI");
    lv_obj_set_style_text_font(ai_text, FONT_BODY, 0);
    lv_obj_set_style_text_color(ai_text, lv_color_hex(COL_TEXT), 0);
    lv_obj_center(ai_text);

    /* Status column */
    lv_obj_t *status_col = make_clean_cont(hero);
    lv_obj_set_flex_grow(status_col, 1);
    lv_obj_set_height(status_col, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(status_col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(status_col, 4, 0);

    lv_obj_t *s1 = lv_label_create(status_col);
