191	void lv_demo_music_play(uint32_t id)
192	{
193	    track_id = id;
194	    update_track_info();
195	    lv_demo_music_resume();
196	}
197	
198	void lv_demo_music_resume(void)
199	{
200	    playing = true;
201	    lv_obj_add_state(play_btn, LV_STATE_CHECKED);
202	    lv_label_set_text(play_icon, LV_SYMBOL_PAUSE);
203	    if (sec_counter_timer) lv_timer_resume(sec_counter_timer);
204	}
205	
206	void lv_demo_music_pause(void)
207	{
208	    playing = false;
209	    lv_obj_remove_state(play_btn, LV_STATE_CHECKED);
210	    lv_label_set_text(play_icon, LV_SYMBOL_PLAY);
211	    if (sec_counter_timer) lv_timer_pause(sec_counter_timer);
212	}
213	
214	void lv_demo_music_album_next(bool next)
215	{
216	    uint32_t max_track = 0;
217	    while (lv_demo_music_get_title(max_track)) max_track++;
218	    if (max_track == 0) return;
219	
220	    if (next) {
221	        track_id = (track_id + 1) % max_track;
222	    } else {
223	        track_id = (track_id == 0) ? max_track - 1 : track_id - 1;
224	    }
225	    lv_demo_music_play(track_id);
226	}
227	
228	/**********************
229	 *   STATIC FUNCTIONS
230	 **********************/
231	
232	static void play_pause_cb(lv_event_t *e)
233	{
234	    lv_obj_t *obj = lv_event_get_target(e);
235	    if (lv_obj_has_state(obj, LV_STATE_CHECKED))
236	        lv_demo_music_resume();
237	    else
238	        lv_demo_music_pause();
239	}
240	
241	static void prev_cb(lv_event_t *e)
242	{
243	    (void)e;
244	    lv_demo_music_album_next(false);
245	}
246	
247	static void next_cb(lv_event_t *e)
248	{
249	    (void)e;
250	    lv_demo_music_album_next(true);
251	}
252	
253	static void timer_cb(lv_timer_t *t)
254	{
255	    (void)t;
256	    if (!playing) return;
257	    uint32_t len = lv_demo_music_get_track_length(track_id);
258	    if (len == 0) return;
259	
260	    int32_t val = lv_slider_get_value(slider_obj);
261	    val++;
262	    if (val > (int32_t)len) {
263	        val = 0;
264	        lv_demo_music_album_next(true);
265	    }
266	    lv_slider_set_value(slider_obj, val, LV_ANIM_OFF);
267	    lv_slider_set_range(slider_obj, 0, len);
268	
269	    char buf[16];
270	    lv_snprintf(buf, sizeof(buf), "%d:%02d", val / 60, val % 60);
271	    lv_label_set_text(time_label, buf);
272	}
273	
274	static void update_track_info(void)
275	{
276	    const char *title = lv_demo_music_get_title(track_id);
277	    const char *artist = lv_demo_music_get_artist(track_id);
278	    uint32_t len = lv_demo_music_get_track_length(track_id);
279	
280	    lv_label_set_text(title_label, title ? title : "Unknown");
281	    lv_label_set_text(artist_label, artist ? artist : "");
282	    lv_slider_set_value(slider_obj, 0, LV_ANIM_OFF);
283	    lv_slider_set_range(slider_obj, 0, len);
284	
285	    char buf[16];
286	    lv_snprintf(buf, sizeof(buf), "0:00");
287	    lv_label_set_text(time_label, buf);
288	}
