37	lv_obj_t * lv_demo_music_list_create(lv_obj_t * parent)
38	{
39	    lv_coord_t sw = lv_disp_get_hor_res(lv_disp_get_default());
40	
41	    /* ── Liquid Glass card for list ── */
42	    list_cont = lv_obj_create(parent);
43	    lv_obj_set_size(list_cont, LV_MIN(sw - 80, 800), LV_SIZE_CONTENT);
44	    lv_obj_set_style_bg_color(list_cont, lv_color_hex(COL_CARD), 0);
45	    lv_obj_set_style_bg_opa(list_cont, LV_OPA_60, 0);
46	    lv_obj_set_style_border_width(list_cont, 1, 0);
47	    lv_obj_set_style_border_color(list_cont, lv_color_hex(COL_CARD), 0);
48	    lv_obj_set_style_border_opa(list_cont, LV_OPA_50, 0);
49	    lv_obj_set_style_shadow_width(list_cont, 8, 0);
50	    lv_obj_set_style_shadow_color(list_cont, lv_color_hex(0x000000), 0);
51	    lv_obj_set_style_shadow_opa(list_cont, LV_OPA_10, 0);
52	    lv_obj_set_style_radius(list_cont, 24, 0);
53	    lv_obj_set_style_pad_all(list_cont, 8, 0);
54	    lv_obj_set_width(list_cont, lv_pct(100));
55	    lv_obj_remove_flag(list_cont, LV_OBJ_FLAG_SCROLLABLE);
56	
57	    /* Flex column for track items */
58	    lv_obj_set_flex_flow(list_cont, LV_FLEX_FLOW_COLUMN);
59	    lv_obj_set_style_pad_row(list_cont, 2, 0);
60	
61	    uint32_t track_id;
62	    for (track_id = 0; lv_demo_music_get_title(track_id); track_id++) {
63	        const char *title = lv_demo_music_get_title(track_id);
64	        const char *artist = lv_demo_music_get_artist(track_id);
65	        uint32_t len = lv_demo_music_get_track_length(track_id);
66	
67	        char time_buf[16];
68	        lv_snprintf(time_buf, sizeof(time_buf), "%d:%02d", len / 60, len % 60);
69	
70	        /* ── Track item row ── */
71	        lv_obj_t *btn = lv_obj_create(list_cont);
72	        lv_obj_set_size(btn, lv_pct(100), 48);
73	        lv_obj_set_style_bg_opa(btn, LV_OPA_0, 0);
74	        lv_obj_set_style_border_width(btn, 0, 0);
75	        lv_obj_set_style_pad_left(btn, 16, 0);
76	        lv_obj_set_style_pad_right(btn, 16, 0);
77	        lv_obj_set_style_radius(btn, 12, 0);
78	        lv_obj_remove_flag(btn, LV_OBJ_FLAG_SCROLLABLE);
79	        lv_obj_add_flag(btn, LV_OBJ_FLAG_CLICKABLE);
80	        lv_obj_add_event_cb(btn, btn_click_cb, LV_EVENT_CLICKED, NULL);
81	        lv_obj_set_user_data(btn, (void *)(uintptr_t)track_id);
82	
83	        /* Flex row: icon | title+artist | time */
84	        lv_obj_set_flex_flow(btn, LV_FLEX_FLOW_ROW);
85	        lv_obj_set_flex_align(btn, LV_FLEX_ALIGN_START,
86	                              LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
87	        lv_obj_set_style_pad_column(btn, 12, 0);
88	
89	        /* Play icon */
90	        lv_obj_t *icon = lv_label_create(btn);
91	        lv_label_set_text(icon, LV_SYMBOL_PLAY);
92	        lv_obj_set_style_text_font(icon, &lv_font_montserrat_16, 0);
93	        lv_obj_set_style_text_color(icon, lv_color_hex(COL_BLUE), 0);
94	
95	        /* Title + artist column */
96	        lv_obj_t *info_col = lv_obj_create(btn);
97	        lv_obj_set_flex_grow(info_col, 1);
98	        lv_obj_set_height(info_col, LV_SIZE_CONTENT);
99	        lv_obj_set_style_bg_opa(info_col, LV_OPA_0, 0);
100	        lv_obj_set_style_border_width(info_col, 0, 0);
101	        lv_obj_set_style_pad_all(info_col, 0, 0);
102	        lv_obj_set_flex_flow(info_col, LV_FLEX_FLOW_COLUMN);
103	        lv_obj_set_style_pad_row(info_col, 2, 0);
104	        lv_obj_remove_flag(info_col, LV_OBJ_FLAG_SCROLLABLE);
105	
106	        lv_obj_t *title_lbl = lv_label_create(info_col);
107	        lv_label_set_text(title_lbl, title);
108	        lv_obj_set_style_text_font(title_lbl, &lv_font_montserrat_16, 0);
109	        lv_obj_set_style_text_color(title_lbl, lv_color_hex(COL_TEXT), 0);
110	
111	        lv_obj_t *artist_lbl = lv_label_create(info_col);
112	        lv_label_set_text(artist_lbl, artist);
113	        lv_obj_set_style_text_font(artist_lbl, &lv_font_montserrat_14, 0);
114	        lv_obj_set_style_text_color(artist_lbl, lv_color_hex(COL_SEC), 0);
115	
116	        /* Time */
117	        lv_obj_t *time_lbl = lv_label_create(btn);
118	        lv_label_set_text(time_lbl, time_buf);
119	        lv_obj_set_style_text_font(time_lbl, &lv_font_montserrat_14, 0);
120	        lv_obj_set_style_text_color(time_lbl, lv_color_hex(COL_SEC), 0);
121	    }
122	
123	    /* Highlight first track */
124	    lv_demo_music_list_button_check(0, true);
125	
126	    LV_LOG_USER("Track list created (%d tracks)", track_id);
127	    return list_cont;
128	}
129	
130	void lv_demo_music_list_button_check(uint32_t track_id, bool state)
131	{
132	    if (!list_cont) return;
133	    lv_obj_t *btn = lv_obj_get_child(list_cont, track_id);
134	    if (!btn) return;
135	
136	    if (state) {
137	        /* Highlight active track */
138	        lv_obj_set_style_bg_opa(btn, LV_OPA_10, 0);
139	        lv_obj_set_style_bg_color(btn, lv_color_hex(COL_BLUE), 0);
140	        active_btn = btn;
141	    } else {
142	        lv_obj_set_style_bg_opa(btn, LV_OPA_0, 0);
143	    }
144	}
