147	 *   STATIC FUNCTIONS
148	 **********************/
149	
150	static void btn_click_cb(lv_event_t *e)
151	{
152	    lv_obj_t *btn = lv_event_get_target(e);
153	    uint32_t idx = (uint32_t)(uintptr_t)lv_obj_get_user_data(btn);
154	
155	    /* Un-highlight previous */
156	    if (active_btn && active_btn != btn)
157	        lv_demo_music_list_button_check(lv_obj_get_index(active_btn), false);
158	
159	    lv_demo_music_play(idx);
160	}
