/* ================================================================
 * MUSIC SUBPAGE — ported from LVGL music demo (lv_demo_music)
 * Light theme, no intro animation, DM() scaled for 1920x1200.
 * Playback is simulated (progress bar + timer), no audio pipeline.
 * ================================================================ */

#define DM_TRACK_COUNT 10

static const char *dm_track_titles[DM_TRACK_COUNT] = {
    "Waiting for true love", "Need a Better Future", "Vibrations",
    "Why now?", "Never Look Back", "It happened Yesterday",
    "Feeling so High", "Go Deeper", "Find You There", "Until the End",
};

static const char *dm_track_artists[DM_TRACK_COUNT] = {
    "The John Smith Band", "My True Name", "Robotics", "John Smith",
    "My True Name", "Robotics", "Robotics", "Unknown artist",
    "Unknown artist", "Unknown artist",
};

static const uint32_t dm_track_lengths[DM_TRACK_COUNT] = {
    74, 146, 114, 144, 157, 213, 116, 211, 140, 139,
};

static lv_obj_t    *music_play_btn;
static lv_obj_t    *music_play_icon;
static lv_obj_t    *music_slider;
static lv_obj_t    *music_time_lbl;
static lv_obj_t    *music_title_lbl;
static lv_obj_t    *music_artist_lbl;
static lv_obj_t    *music_list_cont;
static lv_obj_t    *music_active_btn;
static uint32_t     music_track_id;
static bool         music_playing;

static void music_play(uint32_t id);
static void music_resume(void);
static void music_pause(void);
static void music_album_next(bool next);
static void music_update_track_info(void);
static void music_list_check(uint32_t track_id, bool state);

static void music_timer_cb(lv_timer_t *t)
{
    (void)t;
    if (!music_playing) return;
    uint32_t len = dm_track_lengths[music_track_id];
    if (len == 0) return;

    int32_t val = lv_slider_get_value(music_slider);
    val++;
    if (val > (int32_t)len) {
        val = 0;
        music_album_next(true);
        return;
    }
    lv_slider_set_value(music_slider, val, LV_ANIM_OFF);
    lv_slider_set_range(music_slider, 0, len);

    char buf[16];
    snprintf(buf, sizeof(buf), "%d:%02d", val / 60, val % 60);
    lv_label_set_text(music_time_lbl, buf);
}

static void music_play_pause_cb(lv_event_t *e)
{
    lv_obj_t *obj = lv_event_get_target(e);
    if (lv_obj_has_state(obj, LV_STATE_CHECKED))
        music_resume();
    else
        music_pause();
}

static void music_prev_cb(lv_event_t *e)
{
    (void)e;
    music_album_next(false);
}

static void music_next_cb(lv_event_t *e)
{
    (void)e;
    music_album_next(true);
}

static void music_track_click_cb(lv_event_t *e)
{
    lv_obj_t *btn = lv_event_get_target(e);
    uint32_t idx = (uint32_t)(uintptr_t)lv_obj_get_user_data(btn);

    /* Un-highlight previous row */
    if (music_active_btn && music_active_btn != btn)
        lv_obj_set_style_bg_opa(music_active_btn, LV_OPA_0, 0);

    lv_obj_set_style_bg_opa(btn, LV_OPA_10, 0);
    lv_obj_set_style_bg_color(btn, lv_color_hex(COL_BLUE), 0);
    music_active_btn = btn;

    music_play(idx);
}

static void music_play(uint32_t id)
{
    music_track_id = id;
    music_update_track_info();
    music_resume();
}

static void music_resume(void)
{
    music_playing = true;
    lv_obj_add_state(music_play_btn, LV_STATE_CHECKED);
    lv_label_set_text(music_play_icon, LV_SYMBOL_PAUSE);
    if (g_music_timer) lv_timer_resume(g_music_timer);
}

static void music_pause(void)
{
    music_playing = false;
    lv_obj_remove_state(music_play_btn, LV_STATE_CHECKED);
    lv_label_set_text(music_play_icon, LV_SYMBOL_PLAY);
    if (g_music_timer) lv_timer_pause(g_music_timer);
}

static void music_album_next(bool next)
{
    if (next) {
        music_track_id = (music_track_id + 1) % DM_TRACK_COUNT;
    } else {
        music_track_id =
            (music_track_id == 0) ? DM_TRACK_COUNT - 1 : music_track_id - 1;
    }
    music_play(music_track_id);
}

static void music_update_track_info(void)
{
    lv_label_set_text(music_title_lbl, dm_track_titles[music_track_id]);
    lv_label_set_text(music_artist_lbl, dm_track_artists[music_track_id]);
    lv_slider_set_value(music_slider, 0, LV_ANIM_OFF);
    lv_slider_set_range(music_slider, 0, dm_track_lengths[music_track_id]);
    lv_label_set_text(music_time_lbl, "0:00");

    /* Move highlight to the current row */
    if (music_list_cont) {
        lv_obj_t *row = lv_obj_get_child(music_list_cont, music_track_id);
        if (row) {
            if (music_active_btn && music_active_btn != row)
                lv_obj_set_style_bg_opa(music_active_btn, LV_OPA_0, 0);
            lv_obj_set_style_bg_opa(row, LV_OPA_10, 0);
            lv_obj_set_style_bg_color(row, lv_color_hex(COL_BLUE), 0);
            music_active_btn = row;
        }
    }
}

