    lv_obj_set_style_bg_color(prev_btn, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(prev_btn, LV_OPA_10, 0);
    lv_obj_set_style_border_width(prev_btn, 0, 0);
    lv_obj_add_event_cb(prev_btn, music_prev_cb, LV_EVENT_CLICKED, NULL);
