    lv_obj_set_style_text_font(next_icon, FONT_BODY, 0);
    lv_obj_set_style_text_color(next_icon, lv_color_hex(COL_TEXT), 0);
    lv_obj_center(next_icon);

    /* ── Track list card ── */
    lv_obj_t *list_card = settings_group_card(parent);
    music_list_cont = list_card;

    for (uint32_t i = 0; i < DM_TRACK_COUNT; i++) {
        lv_obj_t *row = make_clean_cont(list_card);
        lv_obj_set_size(row, lv_pct(100), SETTING_ROW_H);
        lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START,
                              LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_column(row, 12, 0);
        lv_obj_set_style_radius(row, 12, 0);
