        lv_obj_add_event_cb(row, music_track_click_cb, LV_EVENT_CLICKED, NULL);
        lv_obj_set_user_data(row, (void *)(uintptr_t)i);

        lv_obj_t *icon = lv_label_create(row);
        lv_label_set_text(icon, LV_SYMBOL_PLAY);
        lv_obj_set_style_text_font(icon, FONT_BODY, 0);
        lv_obj_set_style_text_color(icon, lv_color_hex(COL_BLUE), 0);

        /* Title + artist column */
        lv_obj_t *info_col = make_clean_cont(row);
        lv_obj_set_flex_grow(info_col, 1);
        lv_obj_set_height(info_col, LV_SIZE_CONTENT);
        lv_obj_set_flex_flow(info_col, LV_FLEX_FLOW_COLUMN);
        lv_obj_set_style_pad_row(info_col, 2, 0);

        lv_obj_t *title_lbl = lv_label_create(info_col);
        lv_label_set_text(title_lbl, dm_track_titles[i]);
        lv_obj_set_style_text_font(title_lbl, FONT_BODY, 0);
        lv_obj_set_style_text_color(title_lbl, lv_color_hex(COL_TEXT), 0);

        lv_obj_t *artist_lbl = lv_label_create(info_col);
        lv_label_set_text(artist_lbl, dm_track_artists[i]);
        lv_obj_set_style_text_font(artist_lbl, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(artist_lbl, lv_color_hex(COL_SEC), 0);

        /* Duration */
        char time_buf[16];
        snprintf(time_buf, sizeof(time_buf), "%d:%02d",
                 dm_track_lengths[i] / 60, dm_track_lengths[i] % 60);
        lv_obj_t *time_lbl = lv_label_create(row);
        lv_label_set_text(time_lbl, time_buf);
        lv_obj_set_style_text_font(time_lbl, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(time_lbl, lv_color_hex(COL_SEC), 0);

        if (i < DM_TRACK_COUNT - 1)
            settings_add_separator(list_card);
    }

    /* Progress timer — created paused, no auto-play, no intro animation */
    if (g_music_timer) {
        lv_timer_del(g_music_timer);
        g_music_timer = NULL;
    }
    g_music_timer = lv_timer_create(music_timer_cb, 1000, NULL);
    lv_timer_pause(g_music_timer);
    music_playing = false;
    music_active_btn = NULL;
    music_track_id = 0;
}

