static void music_track_click_cb(lv_event_t *e)
{
    lv_obj_t *btn = lv_event_get_target(e);
    uint32_t idx = (uint32_t)(uintptr_t)lv_obj_get_user_data(btn);

    /* Un-highlight previous row */
    if (music_active_btn && music_active_btn != btn)
        lv_obj_set_style_bg_opa(music_active_btn, LV_OPA_0, 0);

    lv_obj_set_style_bg_opa(btn, LV_OPA_10, 0);
    lv_obj_set_style_bg_color(btn, lv_color_hex(COL_BLUE), 0);
    music_active_btn = btn;

    /* Close playlist overlay and start playback */
    if (music_playlist_overlay)
        lv_obj_add_flag(music_playlist_overlay, LV_OBJ_FLAG_HIDDEN);

    music_play(idx);
}

