static void music_update_track_info(void)
{
    lv_label_set_text(music_title_lbl, dm_track_titles[music_track_id]);
    lv_label_set_text(music_artist_lbl, dm_track_artists[music_track_id]);
    lv_slider_set_value(music_slider, 0, LV_ANIM_OFF);
    lv_slider_set_range(music_slider, 0, dm_track_lengths[music_track_id]);
    lv_label_set_text(music_time_lbl, "0:00");

    char tbuf[16];
    snprintf(tbuf, sizeof(tbuf), "%d:%02d",
             (int)(dm_track_lengths[music_track_id] / 60),
             (int)(dm_track_lengths[music_track_id] % 60));
    if (music_time_total_lbl) lv_label_set_text(music_time_total_lbl, tbuf);

    /* Move highlight to the current row in the playlist overlay */
    if (music_list_cont) {
        lv_obj_t *row = lv_obj_get_child(music_list_cont, music_track_id);
        if (row) {
            if (music_active_btn && music_active_btn != row)
                lv_obj_set_style_bg_opa(music_active_btn, LV_OPA_0, 0);
            lv_obj_set_style_bg_opa(row, LV_OPA_10, 0);
            lv_obj_set_style_bg_color(row, lv_color_hex(COL_BLUE), 0);
            music_active_btn = row;
        }
    }
}

