static void create_books_subpage(lv_obj_t *parent)
{
    lv_coord_t sw = lv_disp_get_hor_res(lv_disp_get_default());

    /* Column layout — vertically centered like the Music player */
    lv_obj_set_flex_flow(parent, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(parent, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(parent, CARD_GAP, 0);

    /* ── Currently Reading (Hero card) ── */
    lv_obj_t *hero = lv_obj_create(parent);
    lv_obj_set_size(hero, lv_pct(100), DM(140));
    lv_obj_add_style(hero, &style_card, 0);
    lv_obj_set_style_pad_all(hero, 16, 0);
    lv_obj_set_scrollbar_mode(hero, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(hero, LV_OBJ_FLAG_SCROLLABLE);

    /* Hero uses flex row: cover | text column */
    lv_obj_set_flex_flow(hero, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(hero, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(hero, 16, 0);

    /* Book cover — colored square accent with soft glow */
    lv_obj_t *cover = lv_obj_create(hero);
    lv_obj_set_size(cover, DM(64), DM(92));
    lv_obj_set_style_radius(cover, 10, 0);
    lv_obj_set_style_bg_color(cover, lv_color_hex(COL_RED), 0);
    lv_obj_set_style_bg_opa(cover, LV_OPA_COVER, 0);
    lv_obj_set_style_shadow_width(cover, 8, 0);
    lv_obj_set_style_shadow_color(cover, lv_color_hex(COL_RED), 0);
    lv_obj_set_style_shadow_opa(cover, LV_OPA_30, 0);
    lv_obj_set_style_border_width(cover, 0, 0);
    lv_obj_set_scrollbar_mode(cover, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(cover, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *cover_icon = lv_label_create(cover);
    lv_label_set_text(cover_icon, LV_SYMBOL_FILE);
    lv_obj_set_style_text_font(cover_icon, FONT_BODY, 0);
    lv_obj_set_style_text_color(cover_icon, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_text_opa(cover_icon, LV_OPA_80, 0);
    lv_obj_center(cover_icon);

    /* Text column: title, author, progress — dark text on white glass */
    lv_obj_t *info_col = make_clean_cont(hero);
    lv_obj_set_flex_grow(info_col, 1);
    lv_obj_set_height(info_col, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(info_col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(info_col, 4, 0);

    lv_obj_t *btitle = lv_label_create(info_col);
    lv_label_set_text(btitle, "The Three-Body Problem");
    lv_obj_set_style_text_font(btitle, FONT_BODY, 0);
    lv_obj_set_style_text_color(btitle, lv_color_hex(COL_TEXT), 0);

    lv_obj_t *author = lv_label_create(info_col);
    lv_label_set_text(author, "Liu Cixin");
    lv_obj_set_style_text_font(author, FONT_CAPTION, 0);
    lv_obj_set_style_text_color(author, lv_color_hex(COL_SEC), 0);

    lv_obj_t *prog = lv_label_create(info_col);
    lv_label_set_text(prog, "72% completed");
    lv_obj_set_style_text_font(prog, FONT_CAPTION, 0);
    lv_obj_set_style_text_color(prog, lv_color_hex(COL_BLUE), 0);

    /* ── Bookshelf grid ── */
    static const struct {
        const char *title;
        const char *author;
        uint32_t    color;
    } shelf[] = {
        { "Dune",        "Frank Herbert",   0xD35400 },
        { "Foundation",  "Isaac Asimov",    0x8E44AD },
        { "Neuromancer", "William Gibson",  0x2980B9 },
        { "Snow Crash",  "Neal Stephenson", 0x16A085 },
    };

    lv_coord_t book_w = (sw - 2 * EDGE_PAD - CARD_GAP) / 2;

    /* Shelf container: flex row wrap */
    lv_obj_t *shelf_cont = make_clean_cont(parent);
    lv_obj_set_width(shelf_cont, lv_pct(100));
    lv_obj_set_height(shelf_cont, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(shelf_cont, LV_FLEX_FLOW_ROW_WRAP);
    lv_obj_set_style_pad_column(shelf_cont, CARD_GAP, 0);
    lv_obj_set_style_pad_row(shelf_cont, CARD_GAP, 0);
    lv_obj_set_flex_align(shelf_cont, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    for (int i = 0; i < 4; i++) {
        lv_obj_t *bcard = lv_obj_create(shelf_cont);
        lv_obj_set_size(bcard, book_w, DM(110));
        lv_obj_add_style(bcard, &style_card, 0);
        lv_obj_set_scrollbar_mode(bcard, LV_SCROLLBAR_MODE_OFF);
        lv_obj_clear_flag(bcard, LV_OBJ_FLAG_SCROLLABLE);

        /* Row layout: mini cover | text column */
        lv_obj_set_flex_flow(bcard, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(bcard, LV_FLEX_ALIGN_START,
                              LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_column(bcard, 12, 0);

        /* Mini cover — accent color square */
        lv_obj_t *mc = lv_obj_create(bcard);
        lv_obj_set_size(mc, DM(44), DM(62));
        lv_obj_set_style_radius(mc, 8, 0);
        lv_obj_set_style_bg_color(mc, lv_color_hex(shelf[i].color), 0);
        lv_obj_set_style_bg_opa(mc, LV_OPA_20, 0);
        lv_obj_set_style_border_width(mc, 0, 0);
        lv_obj_set_scrollbar_mode(mc, LV_SCROLLBAR_MODE_OFF);
        lv_obj_clear_flag(mc, LV_OBJ_FLAG_SCROLLABLE);

        lv_obj_t *mi = lv_label_create(mc);
        lv_label_set_text(mi, LV_SYMBOL_FILE);
        lv_obj_set_style_text_font(mi, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(mi, lv_color_hex(shelf[i].color), 0);
        lv_obj_set_style_text_opa(mi, LV_OPA_80, 0);
        lv_obj_center(mi);

        /* Text column */
        lv_obj_t *tcol = make_clean_cont(bcard);
        lv_obj_set_flex_grow(tcol, 1);
        lv_obj_set_height(tcol, LV_SIZE_CONTENT);
        lv_obj_set_flex_flow(tcol, LV_FLEX_FLOW_COLUMN);
        lv_obj_set_style_pad_row(tcol, 2, 0);

        lv_obj_t *bt = lv_label_create(tcol);
        lv_label_set_text(bt, shelf[i].title);
        lv_obj_set_style_text_font(bt, FONT_BODY, 0);
        lv_obj_set_style_text_color(bt, lv_color_hex(COL_TEXT), 0);

        lv_obj_t *ba = lv_label_create(tcol);
        lv_label_set_text(ba, shelf[i].author);
        lv_obj_set_style_text_font(ba, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(ba, lv_color_hex(COL_SEC), 0);
    }
}

