static void create_files_subpage(lv_obj_t *parent)
{
    /* Column layout — vertically centered like the Music player */
    lv_obj_set_flex_flow(parent, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(parent, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(parent, CARD_GAP, 0);

    /* ── Storage info card ── */
    lv_obj_t *storage = lv_obj_create(parent);
    lv_obj_set_size(storage, lv_pct(100), DM(110));
    lv_obj_add_style(storage, &style_card, 0);
    lv_obj_set_style_pad_all(storage, 16, 0);
    lv_obj_set_scrollbar_mode(storage, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(storage, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_flex_flow(storage, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(storage, 8, 0);

    /* Title row */
    lv_obj_t *title_row = make_clean_cont(storage);
    lv_obj_set_size(title_row, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(title_row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(title_row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    lv_obj_t *st = lv_label_create(title_row);
    lv_label_set_text(st, LV_SYMBOL_DIRECTORY "  Storage");
    lv_obj_set_style_text_font(st, FONT_BODY, 0);
    lv_obj_set_style_text_color(st, lv_color_hex(COL_TEXT), 0);

    lv_obj_t *sd = lv_label_create(title_row);
    lv_label_set_text(sd, "12.4 / 32 GB  (39%)");
    lv_obj_set_style_text_font(sd, FONT_CAPTION, 0);
    lv_obj_set_style_text_color(sd, lv_color_hex(COL_SEC), 0);

    /* Storage bar — thick, blue-purple like the Music progress */
    lv_obj_t *bar = lv_bar_create(storage);
    lv_obj_set_size(bar, lv_pct(100), DM(4));
    lv_obj_set_style_radius(bar, LV_RADIUS_CIRCLE, 0);
    lv_obj_set_style_bg_color(bar, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(bar, LV_OPA_10, 0);
    lv_obj_set_style_bg_color(bar, lv_color_hex(COL_BLUE), LV_PART_INDICATOR);
    lv_obj_set_style_bg_grad_color(bar, lv_color_hex(COL_PURPLE),
                                   LV_PART_INDICATOR);
    lv_obj_set_style_bg_grad_dir(bar, LV_GRAD_DIR_HOR, LV_PART_INDICATOR);
    lv_obj_set_style_radius(bar, LV_RADIUS_CIRCLE, LV_PART_INDICATOR);
    lv_bar_set_range(bar, 0, 100);
    lv_bar_set_value(bar, 39, LV_ANIM_OFF);

    /* ── File list ── */
    static const struct {
        const char *name;
        const char *info;
        const char *symbol;
        uint32_t    color;
    } files[] = {
        { "Documents",   "2.1 GB  ·  Today",      LV_SYMBOL_DIRECTORY, COL_BLUE },
        { "Downloads",   "5.8 GB  ·  Yesterday",   LV_SYMBOL_DIRECTORY, COL_BLUE },
        { "Pictures",    "1.2 GB  ·  Jul 22",      LV_SYMBOL_IMAGE,     COL_ORANGE },
        { "Music",       "800 MB  ·  Jul 20",      LV_SYMBOL_AUDIO,     COL_PURPLE },
        { "report.pdf",  "12 MB   ·  Jul 22",      LV_SYMBOL_FILE,      COL_SEC },
        { "notes.txt",   "4 KB    ·  Jul 23",      LV_SYMBOL_FILE,      COL_SEC },
    };

    lv_obj_t *file_card = settings_group_card(parent);
    for (int i = 0; i < 6; i++) {
        lv_obj_t *row = make_clean_cont(file_card);
        lv_obj_set_size(row, lv_pct(100), SETTING_ROW_H);
        lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START,
                              LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_column(row, 12, 0);
        lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);

        /* File icon badge — colored square like settings/music rows */
        lv_obj_t *badge = lv_obj_create(row);
        lv_obj_set_size(badge, DM(24), DM(24));
        lv_obj_set_style_radius(badge, 6, 0);
        lv_obj_set_style_bg_color(badge, lv_color_hex(files[i].color), 0);
        lv_obj_set_style_bg_opa(badge, LV_OPA_COVER, 0);
        lv_obj_set_style_border_width(badge, 0, 0);
        lv_obj_set_style_pad_all(badge, 0, 0);
        lv_obj_set_scrollbar_mode(badge, LV_SCROLLBAR_MODE_OFF);
        lv_obj_clear_flag(badge, LV_OBJ_FLAG_SCROLLABLE);

        lv_obj_t *ficon = lv_label_create(badge);
        lv_label_set_text(ficon, files[i].symbol);
        lv_obj_set_style_text_font(ficon, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(ficon, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(ficon);

        /* File name */
        lv_obj_t *fname = lv_label_create(row);
        lv_label_set_text(fname, files[i].name);
        lv_obj_set_style_text_font(fname, FONT_BODY, 0);
        lv_obj_set_style_text_color(fname, lv_color_hex(COL_TEXT), 0);
        lv_obj_set_flex_grow(fname, 1);

        /* File info */
        lv_obj_t *finfo = lv_label_create(row);
        lv_label_set_text(finfo, files[i].info);
        lv_obj_set_style_text_font(finfo, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(finfo, lv_color_hex(COL_SEC), 0);

        /* Arrow */
        lv_obj_t *arrow = lv_label_create(row);
        lv_label_set_text(arrow, LV_SYMBOL_RIGHT);
        lv_obj_set_style_text_font(arrow, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(arrow, lv_color_hex(COL_SEC), 0);

        if (i < 5) settings_add_separator(file_card);
    }
}

