        /* File icon */
        lv_obj_t *ficon = lv_label_create(row);
        lv_label_set_text(ficon, files[i].symbol);
        lv_obj_set_style_text_font(ficon, FONT_BODY, 0);
        lv_obj_set_style_text_color(ficon, lv_color_hex(files[i].color), 0);

        /* File name */
        lv_obj_t *fname = lv_label_create(row);
        lv_label_set_text(fname, files[i].name);
        lv_obj_set_style_text_font(fname, FONT_BODY, 0);
        lv_obj_set_style_text_color(fname, lv_color_hex(COL_TEXT), 0);
        lv_obj_set_flex_grow(fname, 1);

        /* File info */
        lv_obj_t *finfo = lv_label_create(row);
        lv_label_set_text(finfo, files[i].info);
        lv_obj_set_style_text_font(finfo, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(finfo, lv_color_hex(COL_SEC), 0);

        /* Arrow */
