static void create_ai_subpage(lv_obj_t *parent)
{
    lv_coord_t sw = lv_disp_get_hor_res(lv_disp_get_default());

    /* Column layout — vertically centered like the Music player */
    lv_obj_set_flex_flow(parent, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(parent, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(parent, CARD_GAP, 0);

    /* ── AI Hero card: ring + status ── */
    lv_obj_t *hero = lv_obj_create(parent);
    lv_obj_set_size(hero, lv_pct(100), DM(130));
    lv_obj_add_style(hero, &style_card, 0);
    lv_obj_set_style_pad_all(hero, 16, 0);
    lv_obj_set_scrollbar_mode(hero, LV_SCROLLBAR_MODE_OFF);
    lv_obj_clear_flag(hero, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_flex_flow(hero, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(hero, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(hero, 20, 0);

    /* AI ring */
    lv_obj_t *ring_cont = make_clean_cont(hero);
    lv_obj_set_size(ring_cont, DM(72), DM(72));

    lv_obj_t *ring = lv_arc_create(ring_cont);
    lv_obj_set_size(ring, DM(72), DM(72));
    lv_obj_center(ring);
    lv_arc_set_bg_angles(ring, 0, 360);
    lv_arc_set_angles(ring, 0, 300);
    lv_obj_set_style_arc_color(ring, lv_color_hex(COL_BLUE), 0);
    lv_obj_set_style_arc_opa(ring, LV_OPA_20, 0);
    lv_obj_set_style_arc_width(ring, 3, 0);
    lv_obj_remove_flag(ring, LV_OBJ_FLAG_CLICKABLE);

    lv_obj_t *ai_text = lv_label_create(ring_cont);
    lv_label_set_text(ai_text, "AI");
    lv_obj_set_style_text_font(ai_text, FONT_BODY, 0);
    lv_obj_set_style_text_color(ai_text, lv_color_hex(COL_TEXT), 0);
    lv_obj_center(ai_text);

    /* Status column */
    lv_obj_t *status_col = make_clean_cont(hero);
    lv_obj_set_flex_grow(status_col, 1);
    lv_obj_set_height(status_col, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(status_col, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(status_col, 4, 0);

    lv_obj_t *s1 = lv_label_create(status_col);
    lv_label_set_text(s1, "Ready to help");
    lv_obj_set_style_text_font(s1, FONT_BODY, 0);
    lv_obj_set_style_text_color(s1, lv_color_hex(COL_TEXT), 0);

    lv_obj_t *s2 = lv_label_create(status_col);
    lv_label_set_text(s2, "Ask me anything");
    lv_obj_set_style_text_font(s2, FONT_CAPTION, 0);
    lv_obj_set_style_text_color(s2, lv_color_hex(COL_SEC), 0);

    /* ── Quick actions grid: flex row wrap ── */
    static const struct {
        const char *label;
        const char *symbol;
        uint32_t    color;
    } actions[] = {
        { "Voice",    LV_SYMBOL_VOLUME_MAX, COL_BLUE },
        { "Chat",     LV_SYMBOL_KEYBOARD,   COL_GREEN },
        { "Schedule", LV_SYMBOL_LIST,        COL_ORANGE },
        { "Weather",  LV_SYMBOL_GPS,         COL_PURPLE },
        { "Reminder", LV_SYMBOL_BELL,        COL_RED },
        { "Translate",LV_SYMBOL_REFRESH,     COL_BLUE },
    };

    lv_coord_t btn_w = (sw - 2 * EDGE_PAD - 2 * CARD_GAP) / 3;

    lv_obj_t *grid = make_clean_cont(parent);
    lv_obj_set_width(grid, lv_pct(100));
    lv_obj_set_height(grid, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(grid, LV_FLEX_FLOW_ROW_WRAP);
    lv_obj_set_style_pad_column(grid, CARD_GAP, 0);
    lv_obj_set_style_pad_row(grid, CARD_GAP, 0);
    lv_obj_set_flex_align(grid, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    for (int i = 0; i < 6; i++) {
        /* Vertical card: colored badge on top, label below */
        lv_obj_t *card = lv_obj_create(grid);
        lv_obj_set_size(card, btn_w, DM(100));
        lv_obj_add_style(card, &style_card, 0);
        lv_obj_set_style_pad_all(card, 12, 0);
        lv_obj_set_scrollbar_mode(card, LV_SCROLLBAR_MODE_OFF);
        lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
        lv_obj_set_flex_align(card, LV_FLEX_ALIGN_CENTER,
                              LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_row(card, 10, 0);

        /* Colored badge like Games/Files — echoes Music cover */
        lv_obj_t *badge = lv_obj_create(card);
        lv_obj_set_size(badge, DM(36), DM(36));
        lv_obj_set_style_radius(badge, 9, 0);
        lv_obj_set_style_bg_color(badge, lv_color_hex(actions[i].color), 0);
        lv_obj_set_style_bg_opa(badge, LV_OPA_COVER, 0);
        lv_obj_set_style_shadow_width(badge, 6, 0);
        lv_obj_set_style_shadow_color(badge, lv_color_hex(actions[i].color), 0);
        lv_obj_set_style_shadow_opa(badge, LV_OPA_30, 0);
        lv_obj_set_style_border_width(badge, 0, 0);
        lv_obj_set_style_pad_all(badge, 0, 0);
        lv_obj_set_scrollbar_mode(badge, LV_SCROLLBAR_MODE_OFF);
        lv_obj_clear_flag(badge, LV_OBJ_FLAG_SCROLLABLE);

        lv_obj_t *icon = lv_label_create(badge);
        lv_label_set_text(icon, actions[i].symbol);
        lv_obj_set_style_text_font(icon, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(icon, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(icon);

        lv_obj_t *lbl = lv_label_create(card);
        lv_label_set_text(lbl, actions[i].label);
        lv_obj_set_style_text_font(lbl, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(lbl, lv_color_hex(COL_TEXT), 0);
    }
}

